var logout = async (req, res, next) => {
  const authorization = req.header("authorization");
  const parts = authorization?.split(" ") ?? [];
  const token = parts[0] === "Bearer" && parts[1]?.trim() ? parts[1].trim() : null;
  if (!token) {
    res.status(400).json({ message: "Missing Bearer token" });
    return;
  }
  try {
    const config2 = getJwtConfig();
    const expiresIn = config2?.expiresIn ?? "12h";
    const expiresAt = new Date(Date.now() + parseExpiryMs(expiresIn));
    await TokenBlacklist_default.updateOne({ token }, { $setOnInsert: { token, userId: req.user?.id, expiresAt } }, { upsert: true });
    res.status(200).json({ message: "Logged out successfully" });
  } catch (error51) {
    next(error51);
  }
};
function parseExpiryMs(value) {
  const num = parseInt(value, 10);
  if (!Number.isNaN(num) && String(num) === value)
    return num * 1000;
  const unit = value.slice(-1);
  const amount = parseInt(value.slice(0, -1), 10);
  if (Number.isNaN(amount))
    return 12 * 60 * 60 * 1000;
  switch (unit) {
    case "s":
      return amount * 1000;
    case "m":
      return amount * 60 * 1000;
    case "h":
      return amount * 60 * 60 * 1000;
    case "d":
      return amount * 24 * 60 * 60 * 1000;
    default:
      return 12 * 60 * 60 * 1000;
  }
}

