var registerPhone = async (req, res, next) => {
  const parsed = phoneRegisterBodySchema.safeParse(req.body);
  if (!parsed.success) {
    res.status(400).json({
      error: "Validation failed",
      code: "VALIDATION_ERROR",
      details: parsed.error.issues
    });
    return;
  }
  let identity;
  try {
    identity = await verifyFirebaseIdToken(parsed.data.firebaseIdToken);
  } catch (error51) {
    if (handleFirebaseAuthError(error51, res))
      return;
    next(error51);
    return;
  }
  const { firebaseUid, phoneNumber } = identity;
  const { name, goal, age, gender } = parsed.data;
  const last10 = phoneNumber.replace(/\D/g, "").slice(-10);
  try {
    const existing = await User_default.findOne({
      $or: [{ firebaseUid }, { phone: { $regex: new RegExp(last10 + "$") } }]
    }).select("email onboarded onboardingStatus");
    if (existing) {
      const auth2 = buildAuthResponse(existing);
      if (!auth2) {
        res.status(503).json({
          error: "JWT authentication is not configured",
          code: "NOT_IMPLEMENTED"
        });
        return;
      }
      res.status(200).json({ message: "Login successful", isNewUser: false, ...auth2 });
      return;
    }
    let createdUser;
    try {
      createdUser = await User_default.create({
        username: name,
        phone: last10,
        firebaseUid,
        phoneVerified: true,
        age,
        gender,
        goal,
        onboardingStatus: defaultOnboardingStatus()
      });
    } catch (error51) {
      if (error51.code === 11000) {
        const raced = await User_default.findOne({
          $or: [{ firebaseUid }, { phone: { $regex: new RegExp(last10 + "$") } }]
        }).select("email onboarded onboardingStatus");
        if (raced) {
          const auth2 = buildAuthResponse(raced);
          if (auth2) {
            res.status(200).json({ message: "Login successful", isNewUser: false, ...auth2 });
            return;
          }
        }
      }
      throw error51;
    }
    try {
      await Lead_default.findOneAndUpdate({ phone: { $regex: new RegExp(last10 + "$") } }, {
        $set: {
          leadName: name,
          phone: last10,
          notes: `Age: ${age}, Gender: ${gender}`,
          interestedIn: goal,
          source: "app-signup",
          status: "New" /* New */,
          convertedUser: createdUser._id
        },
        $addToSet: { tags: { $each: ["signup", "app-signup"] } }
      }, { upsert: true, new: true });
    } catch (err) {
      console.error("[AUTH][PHONE-REGISTER] Lead upsert failed — signup still succeeded:", err);
    }
    const auth = buildAuthResponse(createdUser);
    if (!auth) {
      res.status(503).json({
        error: "JWT authentication is not configured",
        code: "NOT_IMPLEMENTED"
      });
      return;
    }
    res.status(201).json({
      message: "User signup successful",
      isNewUser: true,
      ...auth
    });
  } catch (error51) {
    next(error51);
  }
};

