// src/services/capacity-engine.service.ts
async function allocateSeatAtomic(sessionId) {
  const session = await ScheduledSession_default.findOne({ _id: sessionId });
  if (!session) {
    return { success: false, reason: "SESSION_NOT_FOUND" };
  }
  if (session.status === "CANCELLED" || session.status === "COMPLETED") {
    return { success: false, reason: `SESSION_${session.status}` };
  }
  const updatedSession = await ScheduledSession_default.findOneAndUpdate({
    _id: sessionId,
    status: { $in: ["SCHEDULED"] },
    remainingCapacity: { $gt: 0 }
  }, {
    $inc: {
      currentBookings: 1,
      remainingCapacity: -1
    }
  }, { new: true });
  if (!updatedSession) {
    return { success: false, reason: "FULL_OR_LOCKED" };
  }
  if (updatedSession.remainingCapacity === 0 && updatedSession.status !== "FULL") {
    updatedSession.status = "FULL";
    await updatedSession.save();
  }
  return { success: true, session: updatedSession };
}
async function releaseSeatAtomic(sessionId) {
  const updatedSession = await ScheduledSession_default.findOneAndUpdate({
    _id: sessionId,
    currentBookings: { $gt: 0 }
  }, {
    $inc: {
      currentBookings: -1,
      remainingCapacity: 1
    }
  }, { new: true });
  if (!updatedSession) {
    return { success: false, reason: "NO_BOOKINGS_TO_RELEASE" };
  }
  if (updatedSession.status === "FULL" && updatedSession.remainingCapacity > 0) {
    updatedSession.status = "SCHEDULED";
    await updatedSession.save();
  }
  return { success: true, session: updatedSession };
}
async function updateCapacityAdmin(sessionId, newCapacity) {
  const session = await ScheduledSession_default.findById(sessionId);
  if (!session) {
    return { status: 404, message: "Scheduled session not found" };
  }
  if (newCapacity < session.currentBookings) {
    return {
      status: 400,
      message: `Cannot reduce capacity below currently confirmed bookings (${session.currentBookings} confirmed)`,
      confirmedBookings: session.currentBookings
    };
  }
  const newRemaining = newCapacity - session.currentBookings;
  session.capacity = newCapacity;
  session.remainingCapacity = newRemaining;
  if (newRemaining === 0 && session.status === "SCHEDULED") {
    session.status = "FULL";
  } else if (newRemaining > 0 && session.status === "FULL") {
    session.status = "SCHEDULED";
  }
  await session.save();
  return {
    status: 200,
    message: "Capacity updated successfully",
    session
  };
}

// src/services/cancellation-engine.service.ts
async function cancelBooking(params) {
  const now = params.now || new Date;
  const booking = await Bookings_default.findById(params.bookingId);
  if (!booking) {
    return {
      success: false,
      statusCode: 404,
      message: "Booking not found"
    };
  }
  if (params.requesterRole === "user" && booking.user.toString() !== params.requesterId) {
    return {
      success: false,
      statusCode: 403,
      message: "Forbidden: You cannot cancel another member's booking"
    };
  }
  if (booking.status === "Cancelled" || booking.status === "CANCELLED" || booking.status === 2) {
    return {
      success: false,
      statusCode: 400,
      message: "Booking is already cancelled"
    };
  }
  let sessionStartDateTime = new Date(booking.bookingDate);
  if (booking.startTime) {
    const [hours, minutes] = String(booking.startTime).split(":").map(Number);
    sessionStartDateTime.setHours(hours, minutes, 0, 0);
  }
  if (booking.sessionId) {
    const session = await ScheduledSession_default.findById(booking.sessionId).lean();
    if (session) {
      const [hours, minutes] = String(session.startTime).split(":").map(Number);
      sessionStartDateTime = new Date(session.sessionDate);
      sessionStartDateTime.setHours(hours, minutes, 0, 0);
    }
  }
  const msUntilStart = sessionStartDateTime.getTime() - now.getTime();
  const hoursUntilStart = msUntilStart / (1000 * 60 * 60);
  const isEarlyCancellation = hoursUntilStart >= 24;
  const isAdminOverride = params.requesterRole === "admin" && Boolean(params.adminOverride);
  const shouldRefundCredits = isEarlyCancellation || isAdminOverride;
  booking.status = "Cancelled";
  await booking.save();
  if (booking.sessionId) {
    await releaseSeatAtomic(booking.sessionId);
  }
  let creditRefunded = 0;
  if (shouldRefundCredits) {
    try {
      await refundCreditsBySource({
        userId: booking.user.toString(),
        sourceType: "Booking" /* Booking */,
        sourceId: booking._id.toString(),
        actorId: params.requesterId,
        actorRole: params.requesterRole,
        reason: isAdminOverride ? `Admin override refund for cancelled booking ${booking._id.toString()}` : `Early cancellation refund for booking ${booking._id.toString()}`
      });
      creditRefunded = booking.creditCostSnapshot || 1;
    } catch (error51) {
      console.warn("[CANCELLATION_REFUND_NOTICE]", error51);
    }
  }
  return {
    success: true,
    statusCode: 200,
    message: shouldRefundCredits ? "Booking cancelled successfully. Credits refunded." : "Late cancellation policy applied: seat released, credits forfeited.",
    refunded: shouldRefundCredits,
    latePenaltyApplied: !shouldRefundCredits,
    creditRefunded,
    booking: {
      id: booking._id.toString(),
      status: booking.status,
      refunded: shouldRefundCredits,
      cancelledAt: new Date
    }
  };
}

