    map2.set(String(u._id), {
      id: String(u._id),
      name: profiles.get(String(u._id))?.displayName || u.username || null,
      role: "member",
      avatarUrl: null
    });
  for (const t2 of trainers)
    map2.set(String(t2._id), {
      id: String(t2._id),
      name: profiles.get(String(t2._id))?.displayName || t2.trainerName || null,
      role: "trainer",
      avatarUrl: profiles.get(String(t2._id))?.avatarThumbKey || t2.imageUrl || null
    });
  for (const a of admins)
    map2.set(String(a._id), {
      id: String(a._id),
      name: profiles.get(String(a._id))?.displayName || a.adminName || null,
      role: "admin",
      avatarUrl: null
    });
  for (const [id, author] of map2) {
    if (author.avatarUrl === null) {
      author.avatarUrl = profiles.get(id)?.avatarThumbKey || null;
    }
  }
