async function processAndUploadAvatar(file2, ownerId) {
  const mime2 = file2.mimetype.toLowerCase();
  if (!AVATAR_MIME_TYPES.includes(mime2)) {
    throw new AvatarUploadError(`Only images are allowed (jpeg, png, webp). Rejected: ${file2.mimetype}`, 415, "UNSUPPORTED_MEDIA_TYPE");
  }
  if (file2.size > communityConfig.maxImageBytes) {
    throw new AvatarUploadError(`Image exceeds the ${communityConfig.maxImageBytes}-byte limit`, 413, "PAYLOAD_TOO_LARGE");
  }
  const expected = mime2 === "image/jpg" ? "image/jpeg" : mime2;
  const signatureOk = await validateFileSignature(file2.path, expected);
  if (!signatureOk) {
    throw new AvatarUploadError("File content does not match an allowed image type", 400, "INVALID_IMAGE");
  }
  let image2;
  try {
    image2 = await Jimp.read(file2.path);
  } catch {
    throw new AvatarUploadError("Image could not be decoded", 400, "INVALID_IMAGE");
  }
  const edge = Math.min(image2.width, image2.height);
  const square = image2.clone().crop({
    x: Math.floor((image2.width - edge) / 2),
    y: Math.floor((image2.height - edge) / 2),
    w: edge,
    h: edge
  });
  const fullPx = communityConfig.avatarVariants.full;
  const thumbPx = communityConfig.avatarVariants.thumb;
  const fullImg = square.clone();
  if (fullImg.width > fullPx)
    fullImg.resize({ w: fullPx, h: fullPx });
  const fullBuf = await fullImg.getBuffer("image/jpeg", { quality: 88 });
  const thumbImg = square.clone();
  if (thumbImg.width > thumbPx)
    thumbImg.resize({ w: thumbPx, h: thumbPx });
  const thumbBuf = await thumbImg.getBuffer("image/jpeg", { quality: 78 });
  const baseKey = `community/profiles/avatars/${ownerId}/${import_node_crypto6.randomUUID()}`;
  const avatarKey = `${baseKey}/avatar.jpg`;
  const avatarThumbKey = `${baseKey}/thumb.jpg`;
  await Promise.all([
    uploadToS3(avatarKey, fullBuf, "image/jpeg"),
    uploadToS3(avatarThumbKey, thumbBuf, "image/jpeg")
  ]);
  return { avatarKey, avatarThumbKey, bytes: file2.size };
}

