async function expireStaleNutritionistBookings(now = new Date) {
  let expired = 0;
  let skipped = 0;
  const pending = await NutritionistBooking_default.find({
    status: "PENDING" /* PENDING */
  }).limit(500).lean();
  for (const row of pending) {
    try {
      const startInstant = combineSessionDateTime(row.bookingDate, row.startTime);
      if (!startInstant || startInstant.getTime() > now.getTime()) {
        continue;
      }
      const claimed = await NutritionistBooking_default.findOneAndUpdate({ _id: row._id, status: "PENDING" /* PENDING */ }, { $set: { status: "RESCHEDULE_REQUIRED" /* RESCHEDULE_REQUIRED */ } }, { returnDocument: "after" });
      if (!claimed) {
        skipped++;
        continue;
      }
      if (row.slotId) {
        try {
          await Slots_default.findByIdAndUpdate(row.slotId, {
            $inc: { remainingCapacity: 1 },
            $set: { isBooked: false }
          });
        } catch (err) {
          console.error(`[nutritionist-expiry] Slot release failed for booking ${String(row._id)}`, err);
        }
      }
      expired++;
    } catch (err) {
      console.error(`[nutritionist-expiry] Failed to expire booking ${String(row._id)}`, err);
      skipped++;
    }
  }
  const graceMs = NUTRI_EXPIRY_GRACE_MINUTES * 60000;
  const accepted = await NutritionistBooking_default.find({
    status: "ACCEPTED" /* ACCEPTED */
  }).limit(500).lean();
  for (const row of accepted) {
    try {
      if (row.meetingStatus === "COMPLETED" /* COMPLETED */) {
        continue;
      }
      const endInstant = combineSessionDateTime(row.bookingDate, row.endTime);
      if (!endInstant) {
        continue;
      }
      if (endInstant.getTime() + graceMs >= now.getTime()) {
        continue;
      }
      const claimed = await NutritionistBooking_default.findOneAndUpdate({ _id: row._id, status: "ACCEPTED" /* ACCEPTED */ }, { $set: { status: "EXPIRED" /* EXPIRED */ } }, { returnDocument: "after" });
      if (!claimed) {
        skipped++;
        continue;
      }
      expired++;
    } catch (err) {
      console.error(`[nutritionist-expiry] Failed to expire accepted booking ${String(row._id)}`, err);
      skipped++;
    }
  }
  return { expired, skipped };
}

