async function finalizeSession(session, opts) {
  const sessionId = String(session._id);
  if (session.status !== "COMPLETED") {
    session.status = "COMPLETED";
    session.endedAt = opts.endedAt ?? new Date;
    session.endedBy = opts.endedBy && import_mongoose66.default.Types.ObjectId.isValid(opts.endedBy) ? new import_mongoose66.default.Types.ObjectId(opts.endedBy) : null;
    await session.save();
  }
  const attendanceResult = await Bookings_default.updateMany({
    sessionId,
    joinedAt: { $ne: null },
    status: nonCancelledBookingStatusFilter
  }, { $set: { status: "Attended", leftAt: new Date } });
  let kicked = [];
  let kickErrors = [];
  if (opts.zegoConfig) {
    const roomId = resolveSessionRoomId(session);
    if (roomId) {
      try {
        const result = await forceDisconnectRoom({ appId: opts.zegoConfig.appId, serverSecret: opts.zegoConfig.serverSecret }, roomId, opts.reason);
        kicked = result.kicked;
        kickErrors = result.errors;
      } catch (error51) {
        kickErrors = [
          {
            userIds: [],
            message: error51 instanceof Error ? error51.message : String(error51)
          }
        ];
      }
    }
  }
  return { attendanceMarked: attendanceResult.modifiedCount, kicked, kickErrors };
}

