var norm = (s3) => s3.trim().toLowerCase();
var collectAllergenWarnings = async (userId, days) => {
  const userObjectId = toObjectId2(userId, "BAD_REQUEST", "Invalid user ID");
  const profile = await nutrition_profile_model_default.findOne({ userId: userObjectId }).select("allergies").lean();
  const allergies = profile?.allergies ?? [];
  if (allergies.length === 0)
    return [];
  const allergySet = new Set(allergies.map(norm));
  const foodIds = new Set;
  for (const day of days) {
    for (const meal of day.meals ?? []) {
      for (const item of meal.items ?? []) {
        if (item.foodId)
          foodIds.add(String(item.foodId));
      }
      for (const opt2 of meal.options ?? []) {
        for (const item of opt2.foods ?? []) {
          if (item.foodId)
            foodIds.add(String(item.foodId));
        }
      }
    }
  }
  if (foodIds.size === 0)
    return [];
  const foods = await nutrition_food_model_default.find({ _id: { $in: [...foodIds] } }).select("_id allergens").lean();
  const allergensByFood = new Map;
  for (const food of foods) {
    allergensByFood.set(String(food._id), (food.allergens ?? []).filter((a) => allergySet.has(norm(a))));
  }
  const warnings = [];
  const visit2 = (day, meal, item) => {
    const foodIdStr = String(item.foodId);
    const matched = allergensByFood.get(foodIdStr) ?? [];
    if (matched.length > 0) {
      warnings.push({
        dayNumber: day.dayNumber,
        mealName: meal.name ?? "",
        foodId: foodIdStr,
        foodName: item.foodName,
        matchedAllergens: matched
      });
    }
  };
  for (const day of days) {
    for (const meal of day.meals ?? []) {
      for (const item of meal.items ?? [])
        visit2(day, meal, item);
      for (const opt2 of meal.options ?? []) {
        for (const item of opt2.foods ?? [])
          visit2(day, meal, item);
      }
    }
  }
  return warnings;
};
