var getMyHydration = async (req, res, next) => {
  const requester = req.user;
  if (!requester) {
    res.status(401).json({ error: "Unauthorized", code: "UNAUTHORIZED" });
    return;
  }
  const parsed = hydrationQuerySchema.safeParse(req.query);
  if (!parsed.success) {
    res.status(400).json({
      error: "Validation failed",
      code: "VALIDATION_ERROR",
      details: getValidationDetails2(parsed.error.issues)
    });
    return;
  }
  try {
    const isStaff = ["nutritionist", "admin"].includes(requester.role);
    const targetUserId = isStaff && parsed.data.userId ? parsed.data.userId : requester.id;
    const hydration = await getHydration(targetUserId, parsed.data.date);
    let items = [];
    if (hydration) {
      if (hydration.entries && hydration.entries.length > 0) {
        items = hydration.entries.map((entry, index) => ({
          _id: `${hydration._id}_${index}`,
          userId: hydration.userId.toString(),
          date: hydration.logDate.toISOString(),
          glasses: entry.amountMl / 250,
          ml: entry.amountMl,
          targetMl: hydration.goalMl,
          loggedAt: entry.at ? entry.at.toISOString() : undefined
        }));
      } else {
        items = [
          {
            _id: hydration._id.toString(),
            userId: hydration.userId.toString(),
            date: hydration.logDate.toISOString(),
            glasses: hydration.totalMl / 250,
            ml: hydration.totalMl,
            targetMl: hydration.goalMl,
            loggedAt: hydration.updatedAt ? hydration.updatedAt.toISOString() : undefined
          }
        ];
      }
    }
    res.status(200).json({ hydration, items });
  } catch (error51) {
    handleNutritionError(error51, res, next);
  }
};

// src/services/nutrition/nutrition-meal-log.service.ts
var assertPlanOwnedByUser = async (planId, userId) => {
  const plan = await nutrition_plan_model_default.findById(planId);
  if (!plan) {
    throw new NutritionServiceError("NOT_FOUND", "Plan not found");
  }
  if (plan.userId.toString() !== userId) {
    throw new NutritionServiceError("FORBIDDEN", "This plan is not assigned to you");
  }
  return plan;
};
var logMeal = async (input, userId) => {
  const userObjectId = toObjectId2(userId, "BAD_REQUEST", "Invalid user ID");
  const logDate = normalizeToUtcDate2(input.logDate ?? new Date);
  let planObjectId = null;
  let dayNumber = null;
  if (input.planId) {
    planObjectId = toObjectId2(input.planId, "NOT_FOUND", "Plan not found");
    const plan = await assertPlanOwnedByUser(planObjectId, userId);
    dayNumber = computeDayNumber(plan.startDate, plan.durationDays, logDate);
  }
  const items = await resolveItemsToSnapshots(input.items);
  const totals = sumMacros(items);
  const log = await nutrition_meal_log_model_default.create({
    userId: userObjectId,
    planId: planObjectId,
    logDate,
    dayNumber,
    plannedMealRef: input.plannedMealRef ?? null,
    status: input.status ?? "Logged" /* Logged */,
    source: input.source ?? "Manual" /* Manual */,
    notes: input.notes ?? "",
    photoUrls: input.photoUrls ?? [],
    items,
    totals
  });
  if (planObjectId) {
    await recomputeDay(userObjectId, planObjectId, logDate);
  }
  return log;
};
var markMealCompleted = async (planId, dayNumber, mealIndex, userId, date5, completedOptionId) => {
  const planObjectId = toObjectId2(planId, "NOT_FOUND", "Plan not found");
  const plan = await assertPlanOwnedByUser(planObjectId, userId);
  const userObjectId = toObjectId2(userId, "BAD_REQUEST", "Invalid user ID");
  const logDate = normalizeToUtcDate2(date5 ?? new Date);
  const planDay = plan.days.find((d) => d.dayNumber === dayNumber);
  const meal = planDay?.meals?.[mealIndex];
  if (!meal) {
    throw new NutritionServiceError("NOT_FOUND", "Prescribed meal not found");
  }
  const optionItems = completedOptionId ? getOptionItems(meal, completedOptionId) : null;
  const sourceItems = optionItems ?? getEffectiveMealItems(meal);
  const items = sourceItems.map((item) => ({
    foodId: item.foodId,
    foodName: item.foodName,
    quantityG: item.quantityG,
    caloriesKcal: item.caloriesKcal,
    proteinG: item.proteinG,
    carbsG: item.carbsG,
    fatG: item.fatG,
    fiberG: item.fiberG ?? null,
    sugarG: item.sugarG ?? null
  }));
  const totals = sumMacros(items);
  const plannedMealRef = {
    dayNumber,
    mealIndex
  };
  if (completedOptionId) {
    plannedMealRef.selectedOptionId = completedOptionId;
    plannedMealRef.completedOptionId = completedOptionId;
  }
  const log = await nutrition_meal_log_model_default.findOneAndUpdate({
    userId: userObjectId,
    planId: planObjectId,
    logDate,
    "plannedMealRef.dayNumber": dayNumber,
    "plannedMealRef.mealIndex": mealIndex
  }, {
    userId: userObjectId,
    planId: planObjectId,
    logDate,
    dayNumber,
    plannedMealRef,
    status: "Logged" /* Logged */,
    source: "Manual" /* Manual */,
    items,
    totals
  }, { upsert: true, returnDocument: "after", runValidators: true });
  await recomputeDay(userObjectId, planObjectId, logDate);
  return log;
};
var loadOwnLog = async (logId, userId) => {
  const id = toObjectId2(logId, "NOT_FOUND", "Meal log not found");
  const log = await nutrition_meal_log_model_default.findById(id);
  if (!log) {
    throw new NutritionServiceError("NOT_FOUND", "Meal log not found");
  }
  if (log.userId.toString() !== userId) {
    throw new NutritionServiceError("FORBIDDEN", "This meal log is not yours");
  }
  return log;
};
var updateMealLog = async (logId, patch, userId) => {
  const log = await loadOwnLog(logId, userId);
  if (patch.status !== undefined) {
    log.set({ status: patch.status });
  }
  if (patch.notes !== undefined) {
    log.set({ notes: patch.notes });
  }
  if (patch.photoUrls !== undefined) {
    log.set({ photoUrls: patch.photoUrls });
  }
  if (patch.items) {
    const items = await resolveItemsToSnapshots(patch.items);
    log.set({ items, totals: sumMacros(items) });
  }
  await log.save();
  if (log.planId) {
    await recomputeDay(log.userId, log.planId, log.logDate);
  }
  return log;
};
var deleteMealLog = async (logId, userId) => {
  const log = await loadOwnLog(logId, userId);
  const { planId, userId: ownerId, logDate } = log;
  await log.deleteOne();
  if (planId) {
    await recomputeDay(ownerId, planId, logDate);
  }
};
var listLogs = async (userId, filters) => {
  const page = Math.max(1, filters.page ?? 1);
  const limit = Math.min(200, Math.max(1, filters.limit ?? 50));
  const filter = {
    userId: toObjectId2(userId, "BAD_REQUEST", "Invalid user ID")
  };
  if (filters.planId) {
    filter.planId = toObjectId2(filters.planId, "BAD_REQUEST", "Invalid plan ID");
  }
  if (filters.from || filters.to) {
    const range = {};
    if (filters.from) {
      range.$gte = normalizeToUtcDate2(filters.from);
    }
    if (filters.to) {
      range.$lte = normalizeToUtcDate2(filters.to);
    }
    filter.logDate = range;
  }
  const [items, total] = await Promise.all([
    nutrition_meal_log_model_default.find(filter).sort({ logDate: -1, consumedAt: -1 }).skip((page - 1) * limit).limit(limit),
    nutrition_meal_log_model_default.countDocuments(filter)
  ]);
  return { items, total, page, limit };
};

