// src/services/nutrition/nutrition-plan-pdf.service.ts
var generatePlanPdf = async (planId, actor, deps = defaultPdfDeps) => {
  const plan = await getPlan(planId, actor);
  const buffer = await deps.renderer.renderPlanPdf(plan);
  const key = `plans/${plan._id.toString()}/${Date.now()}.pdf`;
  const stored = await deps.storage.put(key, buffer, "application/pdf");
  plan.set({
    hasPdf: true,
    pdfUrl: stored.url,
    pdfStorageKey: stored.key,
    pdfGeneratedAt: new Date
  });
  await plan.save();
  return {
    pdfUrl: plan.pdfUrl,
    pdfGeneratedAt: plan.pdfGeneratedAt
  };
};
var getPlanPdf = async (planId, actor) => {
  const plan = await getPlan(planId, actor);
  if (!plan.hasPdf || !plan.pdfUrl) {
    throw new NutritionServiceError("NOT_FOUND", "No PDF has been generated for this plan");
  }
  return {
    pdfUrl: plan.pdfUrl,
    pdfGeneratedAt: plan.pdfGeneratedAt
  };
};

