var copyPlanDayStructure = async (req, res, next) => {
  const requester = req.user;
  if (!requester) {
    res.status(401).json({ error: "Unauthorized", code: "UNAUTHORIZED" });
    return;
  }
  const parsed = copyDayStructureSchema.safeParse(req.body);
  if (!parsed.success) {
    res.status(400).json({
      error: "Validation failed",
      code: "VALIDATION_ERROR",
      details: getValidationDetails2(parsed.error.issues)
    });
    return;
  }
  try {
    const { planId, sourceDayOfWeek, targetDaysOfWeek, strategy } = parsed.data;
    let document2 = await nutrition_plan_model_default.findById(planId);
    let isTemplate = false;
    if (!document2) {
      document2 = await nutrition_template_model_default.findById(planId);
      isTemplate = true;
    }
    if (!document2) {
      res.status(404).json({ error: "Plan or template not found", code: "NOT_FOUND" });
      return;
    }
    const dayOfWeekToNumber = (day) => {
      const mapping = {
        Sunday: 7,
        Monday: 1,
        Tuesday: 2,
        Wednesday: 3,
        Thursday: 4,
        Friday: 5,
        Saturday: 6
      };
      return mapping[day] ?? 1;
    };
    const sourceDayNum = dayOfWeekToNumber(sourceDayOfWeek);
    const sourceDayDoc = document2.days.find((d) => d.dayNumber === sourceDayNum);
    if (!sourceDayDoc) {
      res.status(400).json({
        error: `Source day (${sourceDayOfWeek}) not configured in the template/plan.`,
        code: "BAD_REQUEST"
      });
      return;
    }
    const stripIds = (obj) => {
      if (Array.isArray(obj)) {
        return obj.map(stripIds);
      } else if (obj !== null && typeof obj === "object") {
        const plainObj = typeof obj.toObject === "function" ? obj.toObject() : { ...obj };
        delete plainObj._id;
        delete plainObj.id;
        for (const key in plainObj) {
          plainObj[key] = stripIds(plainObj[key]);
        }
        return plainObj;
      }
      return obj;
    };
    const sourceMealsPlain = stripIds(sourceDayDoc.meals);
    let targetDayNums = targetDaysOfWeek.map(dayOfWeekToNumber);
    if (strategy === "split_week") {
      const isWeekdaySelected = targetDaysOfWeek.some((d) => ["Monday", "Tuesday", "Wednesday", "Thursday", "Friday"].includes(d));
      if (isWeekdaySelected) {
        targetDayNums = [1, 2, 3, 4, 5];
      } else {
        targetDayNums = [6, 7];
      }
    }
    for (const targetDayNum of targetDayNums) {
      if (targetDayNum === sourceDayNum)
        continue;
      let mealsToCopy = JSON.parse(JSON.stringify(sourceMealsPlain));
      if (strategy === "alternate") {
        const altDayNum = sourceDayNum === 1 ? 2 : 1;
        const altDayDoc = document2.days.find((d) => d.dayNumber === altDayNum);
        if (altDayDoc && targetDayNum % 2 !== sourceDayNum % 2) {
          mealsToCopy = stripIds(altDayDoc.meals);
        }
      }
      const targetDayDoc = document2.days.find((d) => d.dayNumber === targetDayNum);
      if (!targetDayDoc) {
        document2.days.push({
          dayNumber: targetDayNum,
          meals: mealsToCopy
        });
      } else {
        targetDayDoc.meals = mealsToCopy;
      }
    }
    document2.days.sort((a, b) => a.dayNumber - b.dayNumber);
    await document2.save();
    res.status(200).json({
      message: `Day structure replicated to target days successfully.`,
      days: document2.days
    });
  } catch (error51) {
    handleNutritionError(error51, res, next);
  }
};

