var buildMealSnapshotFromRecipe = async (recipeId) => {
  const id = toObjectId2(recipeId, "NOT_FOUND", "Recipe not found");
  const recipe = await Recipe_default.findOne({ _id: id, isActive: true }).lean();
  if (!recipe) {
    throw new NutritionServiceError("NOT_FOUND", "Recipe not found");
  }
  const ingredients = await RecipeIngredient_default.find({ recipeId: id }).sort({ sortOrder: 1 }).lean();
  const skippedIngredients = [];
  const items = [];
  for (const ing of ingredients) {
    if (!ing.foodId) {
      skippedIngredients.push(ing.rawIngredientName);
      continue;
    }
    items.push({
      foodId: ing.foodId,
      foodName: ing.rawIngredientName,
      quantityG: ing.quantity ?? 0,
      unit: ing.unit ?? "g",
      caloriesKcal: ing.caloriesKcal ?? 0,
      proteinG: ing.proteinG ?? 0,
      carbsG: ing.carbsG ?? 0,
      fatG: ing.fatG ?? 0,
      fiberG: ing.fiberG ?? null,
      sugarG: ing.sugarG ?? null
    });
  }
  const totals = sumMacros(items);
  const meal = {
    mealType: recipe.defaultMealType ?? "Lunch" /* Lunch */,
    name: recipe.name,
    recipeId: recipe._id,
    timeOfDay: null,
    notes: "",
    items,
    options: [],
    cookingDirections: recipe.cookingDirections ?? [],
    prepTimeMinutes: recipe.prepTimeMinutes ?? null
  };
  return { meal, totals, skippedIngredients };
};
