  if (recipes.length === 0) {
    throw new NutritionServiceError("NOT_FOUND", "No active recipes found for this category");
  }
  const meals = [];
  const allSkipped = [];
  for (const recipe of recipes) {
    const { meal, skippedIngredients } = await buildMealSnapshotFromRecipe(recipe._id.toString());
    meals.push(meal);
    allSkipped.push(...skippedIngredients);
  }
